package com.enterprise.engine.concurrency;

import sun.misc.Contended;

public final class PaddedSequenceTracker {

    // Using @Contended prevents false sharing between sequence reads and writes
    @Contended
    private volatile long sequenceValue = -1L;

    @Contended
    private volatile long batchSequence = -1L;

    public void updateSequence(long newValue) {
        // Volatile write enforces happens-before relationship
        this.sequenceValue = newValue;
    }

    public long getSequenceValue() {
        return sequenceValue;
    }
}
